    'CSS': ['Aturan yang mengatur warna, jarak, ukuran, tipografi, dan susunan elemen.', 'Cat, papan petunjuk, serta tata letak interior gym.', 'Contoh: assets/css/style.css mengatur sidebar dan tabel lintas halaman.'],
    'JavaScript': ['Bahasa pemrograman di browser yang dapat merespons klik, memvalidasi form, dan memuat data.', 'Saklar dan sensor yang membuat fasilitas bereaksi.', 'Contoh: jobsheet5/assets/js/app.js menangani filter dan validasi.'],
    'Bootstrap': ['Framework antarmuka berisi class dan komponen siap pakai untuk layout responsif.', 'Paket furnitur modular yang bisa dirakit lalu dihias sesuai identitas gym.', 'Contoh: jobsheet3bootstrap memakai grid, card, table, dan form Bootstrap.'],
    'PHP': ['Bahasa pemrograman yang dijalankan di server untuk memproses request dan merender halaman.', 'Petugas administrasi di belakang loket yang memeriksa dan mengurus formulir.', 'Contoh: jobsheet8/kelas/proses_tambah.php menerima dan menyimpan form.'],
    'JSON': ['Format teks untuk menyimpan kumpulan data terstruktur dengan pasangan nama dan nilai.', 'Kartu arsip dengan kolom yang punya label jelas.', 'Contoh: jobsheet6/data/kelas.json.'],
    'fetch': ['Fungsi JavaScript untuk meminta data dari file atau layanan web.', 'Kurir yang mengambil arsip lalu mengantarkannya ke halaman.', 'Contoh: jobsheet6/assets/js/kelas.js meminta ../data/kelas.json.'],
    'API': ['Aturan dan jalur yang memungkinkan program menerima permintaan dari browser atau program lain.', 'Loket tempat bagian lain menyerahkan permintaan dengan format yang disepakati.', 'Contoh: jobsheet13/api/index.php menerima request dan meneruskannya ke halaman PHP.'],
    'database': ['Tempat penyimpanan data terstruktur yang bisa ditanya dan diperbarui melalui program.', 'Lemari arsip bersama, dengan laci dan label yang konsisten.', 'Contoh: tabel kelas, anggota, users, dan pendaftaran di PostgreSQL.'],
