    'SQL': ['Bahasa untuk membuat tabel serta membaca, memasukkan, dan mengubah data database.', 'Instruksi tertulis untuk petugas arsip: buka laci, cari, atau simpan berkas.', 'Contoh: jobsheet8/sql/01_kelas_anggota.sql membuat tabel kelas dan anggota.'],
    'CRUD': ['Create, Read, Update, Delete: empat operasi umum untuk mengelola data.', 'Mengisi, melihat, mengoreksi, lalu mengarsipkan berkas.', 'Jobsheet 9 menambahkan edit dan hapus pada kemampuan baca/tambah Jobsheet 8.'],
    'PDO': ['Antarmuka PHP untuk membuka koneksi database dan menjalankan query.', 'Adaptor yang menghubungkan meja petugas dengan lemari arsip.', 'Contoh: includes/koneksi.php membentuk objek $pdo.'],
    'prepared statement': ['Query yang disiapkan terpisah dari nilai input, agar input diperlakukan sebagai data dan bukan potongan perintah SQL.', 'Form resmi yang punya kolom isian; isi kolom tak dapat mengubah instruksi petugas.', 'Contoh: $pdo->prepare(...), lalu execute([...]) pada file proses.'],
    'session': ['Catatan di server yang mengingat pengguna dan pesan sementara antarhalaman.', 'Kartu penitipan yang menunjukkan siapa pengunjung selama berpindah ruangan.', 'Contoh: jobsheet10 menyimpan user_id setelah login dan membaca flash message.'],
    'autentikasi': ['Proses membuktikan identitas pengguna, biasanya dengan username dan kata sandi.', 'Petugas memeriksa kartu identitas sebelum memberi akses.', 'Contoh: proses_login.php mencari akun lalu memverifikasi password.'],
    'hash': ['Sidik digital satu arah dari kata sandi; sistem membandingkan kata sandi dengan hash tanpa menyimpan aslinya.', 'Sidik jari kata sandi, bukan salinan kata sandi yang bisa dibaca.', 'Contoh: password_hash saat daftar dan password_verify saat login.'],
    'CSRF': ['Serangan yang mencoba membuat browser pengguna mengirim aksi tanpa persetujuan atau alur aplikasi yang benar.', 'Formulir titipan palsu yang diselundupkan melalui pengunjung.', 'Pertahanan pada Jobsheet 11: token acak disimpan di session dan dikirim dalam form.'],
    'token': ['Nilai acak khusus yang dipakai sebagai bukti bahwa form berasal dari session dan alur yang diharapkan.', 'Kode sekali pakai pada kartu akses.', 'Contoh: csrf_field() menaruh token tersembunyi; csrf_verify() memeriksanya.'],
    'foreign key': ['Kolom yang merujuk ke primary key di tabel lain, menjaga relasi antarbaris.', 'Nomor rujukan yang menghubungkan formulir pendaftaran ke arsip anggota dan kelas.', 'Contoh: pendaftaran.kelas_id merujuk kelas.id.'],
    'wireframe': ['Sketsa susunan bagian halaman, sebelum detail warna dan gaya diputuskan.', 'Denah sederhana untuk menentukan pintu, meja, dan ruang sebelum bangunan dihias.', 'Dokumen rancangan proyek tersimpan pada jobsheet4–6/docs/wireframe.md.'],
    'user flow': ['Urutan layar dan tindakan yang dilalui seseorang untuk menyelesaikan tujuan.', 'Rute anggota dari pintu masuk sampai mendaftar kelas.', 'Contoh: login → dashboard → pilih anggota dan kelas → simpan pendaftaran.'],
    'environment variable': ['Konfigurasi yang disediakan oleh lingkungan server, bukan ditulis sebagai rahasia di source code.', 'Kunci brankas yang disimpan terpisah dari denah gedung.', 'Contoh: DB_PASS dibaca oleh koneksi database Jobsheet 7–13.'],
    'front controller': ['Satu file masuk yang memeriksa alamat request lalu meneruskannya ke halaman tujuan.', 'Resepsionis yang memastikan pengunjung menuju ruangan yang diizinkan.', 'Contoh: jobsheet13/api/index.php memakai daftar rute yang diperbolehkan.'],
    'deployment': ['Proses menaruh aplikasi ke hosting/server agar pengguna dapat mengaksesnya.', 'Membuka cabang gym di lokasi yang dapat dikunjungi anggota.', 'Contoh: vercel.json menentukan runtime PHP dan rute aplikasi.'],
    'serverless': ['Model hosting cloud yang mengelola infrastruktur server; aplikasi dijalankan saat ada request.', 'Menyewa fasilitas siap pakai tanpa perlu mengurus ruang mesin sendiri.', 'Proyek menyiapkan runtime PHP serverless di Vercel.'],
    'session flash': ['Pesan sementara di session yang disimpan sebelum redirect lalu dibaca sekali pada halaman berikutnya.', 'Catatan kecil yang dititipkan resepsionis untuk ditampilkan di loket tujuan.', 'Contoh: pesan berhasil atau gagal setelah form disimpan.'],
    'event delegation': ['Pola JavaScript: satu listener di elemen induk menangani klik pada anak yang dibuat kemudian.', 'Satu petugas di pintu mengarahkan siapa pun yang datang, termasuk tamu baru.', 'Dipakai Jobsheet 6 agar tombol pada baris tabel hasil fetch tetap aktif.']
